package com.ntd.csdl;
import com.ntd.csdl.service.*;import com.ntd.csdl.config.RentalJobs;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;import java.time.*;import java.math.*;import java.util.*;import java.util.concurrent.*;
class StayBillingTests {
 JdbcTemplate jdbc;TransactionTemplate tx;MonthlyBillingService bills;StayService stays;LandlordService landlords;
 @BeforeEach void init(){var ds=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;NON_KEYWORDS=YEAR,MONTH,USER;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=5000","sa","");jdbc=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));
 for(String sql:List.of(
 "CREATE TABLE rooms(room_id VARCHAR(20) PRIMARY KEY,status VARCHAR(50),base_price DECIMAL(18,2))",
 "CREATE TABLE contracts(contract_id VARCHAR(20) PRIMARY KEY,room_id VARCHAR(20),tenant_id VARCHAR(20),start_date DATE,end_date DATE)",
 "CREATE TABLE contract_stays(contract_id VARCHAR(20) PRIMARY KEY,check_in DATE,check_out DATE,check_in_electric INT,check_in_water INT,check_out_electric INT,check_out_water INT,monthly_rent DECIMAL(18,2))",
 "CREATE TABLE utility_readings(reading_id VARCHAR(20) PRIMARY KEY,room_id VARCHAR(20),year INT,month INT,electricity_start_index INT,electricity_end_index INT,water_start_index INT,water_end_index INT,electricity_price DECIMAL(18,2),water_price DECIMAL(18,2))",
 "CREATE TABLE invoices(invoice_id VARCHAR(20) PRIMARY KEY,contract_id VARCHAR(20),year INT,month INT,rent_amount DECIMAL(18,2),electricity_amount DECIMAL(18,2),water_amount DECIMAL(18,2),fine_amount DECIMAL(18,2),total_amount DECIMAL(18,2))",
 "CREATE TABLE automatic_bills(contract_id VARCHAR(20),year INT,month INT,invoice_id VARCHAR(20),PRIMARY KEY(contract_id,year,month))",
 "CREATE TABLE billing_alerts(contract_id VARCHAR(20),year INT,month INT,message VARCHAR(500),PRIMARY KEY(contract_id,year,month))",
 "CREATE TABLE tenant_accounts(user_id BIGINT PRIMARY KEY,tenant_id VARCHAR(20) UNIQUE)",
 "CREATE TABLE invoice_notifications(invoice_id VARCHAR(20) PRIMARY KEY,user_id BIGINT,message VARCHAR(300),seen BOOLEAN)",
 "CREATE TABLE payment_reports(payment_report_id BIGINT PRIMARY KEY,invoice_id VARCHAR(20),status VARCHAR(30))"))jdbc.execute(sql);
 jdbc.update("INSERT INTO rooms VALUES('R1','OCCUPIED',9999999)");jdbc.update("INSERT INTO tenant_accounts VALUES(1,'T1'),(2,'T2')");landlords=mock(LandlordService.class);stays=new StayService(jdbc,landlords);bills=new MonthlyBillingService(jdbc);
 }
 void contract(String id,String tenant,LocalDate from,LocalDate to){jdbc.update("INSERT INTO contracts VALUES(?,'R1',?,?,?)",id,tenant,from,to);}
 void janFixture(){contract("C1","T1",LocalDate.of(2026,1,1),LocalDate.of(2026,1,31));jdbc.update("INSERT INTO contract_stays VALUES('C1','2026-01-01',null,300,10,null,null,3100000)");jdbc.update("INSERT INTO utility_readings VALUES('M1','R1',2026,1,300,400,10,20,3500,15000)");}
 String bill(String id){return tx.execute(t->bills.bill(id,YearMonth.of(2026,1)));}
 int count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class);}
 @Test void rentUsesActualDaysAndLeapMonth(){assertEquals(new BigDecimal("1500000.00"),BillingMath.rent(new BigDecimal("3100000"),LocalDate.of(2026,1,1),LocalDate.of(2026,1,15),YearMonth.of(2026,1)));assertEquals(new BigDecimal("100000.00"),BillingMath.rent(new BigDecimal("2900000"),LocalDate.of(2024,2,29),LocalDate.of(2024,2,29),YearMonth.of(2024,2)));}
 @Test void fullMonthUsesAgreedRateAndNotCurrentRoomPrice(){janFixture();assertEquals("CREATED",bill("C1"));assertEquals(new BigDecimal("3600000.00"),jdbc.queryForObject("SELECT total_amount FROM invoices",BigDecimal.class));assertEquals(1,count("invoice_notifications"));assertEquals(1L,jdbc.queryForObject("SELECT user_id FROM invoice_notifications",Long.class));}
 @Test void rerunDoesNotDuplicateInvoicesOrNotifications(){janFixture();bill("C1");assertEquals("EXISTS",bill("C1"));assertEquals(1,count("invoices"));assertEquals(1,count("invoice_notifications"));}
 @Test void missingReadingsWaitAndRetryAfterInput(){janFixture();jdbc.update("DELETE FROM utility_readings");assertEquals("NEEDS_READING",bill("C1"));assertEquals(0,count("invoices"));assertEquals(1,count("billing_alerts"));jdbc.update("INSERT INTO utility_readings VALUES('M1','R1',2026,1,300,400,10,20,3500,15000)");assertEquals("CREATED",bill("C1"));assertEquals(0,count("billing_alerts"));}
 @Test void negativeUsageNeverProducesAnInvoice(){janFixture();jdbc.update("UPDATE utility_readings SET electricity_end_index=200");assertEquals("NEEDS_READING",bill("C1"));assertEquals(0,count("invoices"));}
 @Test void turnoverUsesSeparateMeterSnapshotsAndProratesBothTenants(){janFixture();jdbc.update("UPDATE contract_stays SET check_out='2026-01-16',check_out_electric=350,check_out_water=15");contract("C2","T2",LocalDate.of(2026,1,16),LocalDate.of(2026,1,31));jdbc.update("INSERT INTO contract_stays VALUES('C2','2026-01-16',null,350,15,null,null,3100000)");bill("C1");bill("C2");assertEquals(new BigDecimal("1500000.00"),jdbc.queryForObject("SELECT rent_amount FROM invoices WHERE contract_id='C1'",BigDecimal.class));assertEquals(new BigDecimal("1600000.00"),jdbc.queryForObject("SELECT rent_amount FROM invoices WHERE contract_id='C2'",BigDecimal.class));assertEquals(new BigDecimal("350000.00"),jdbc.queryForObject("SELECT SUM(electricity_amount) FROM invoices",BigDecimal.class));assertEquals(2,count("invoice_notifications"));}
 @Test void incompleteTurnoverMetersAreFlagged(){janFixture();jdbc.update("UPDATE contract_stays SET check_out='2026-01-16'");assertEquals("NEEDS_READING",bill("C1"));assertEquals(0,count("invoices"));}
 @Test void paidInvoiceIsNeverChanged(){janFixture();jdbc.update("INSERT INTO invoices VALUES('OLD','C1',2026,1,3100000,0,0,0,3100000)");jdbc.update("INSERT INTO payment_reports VALUES(1,'OLD','PAID')");assertEquals("MANUAL",bill("C1"));assertEquals(new BigDecimal("3100000.00"),jdbc.queryForObject("SELECT total_amount FROM invoices",BigDecimal.class));assertEquals(1,count("invoices"));}
 @Test void twoWorkersCreateOnlyOneInvoice()throws Exception{janFixture();var a=CompletableFuture.supplyAsync(()->bill("C1"));var b=CompletableFuture.supplyAsync(()->bill("C1"));var results=List.of(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));assertTrue(results.contains("CREATED"));assertTrue(results.contains("EXISTS"));assertEquals(1,count("invoices"));}
 @Test void checkoutReleasesRoomImmediatelyAndPreservesContractDates(){LocalDate now=StayService.today();contract("C1","T1",now.minusDays(10),now.plusMonths(3));jdbc.update("INSERT INTO contract_stays VALUES('C1',?,null,100,10,null,null,3000000)",now.minusDays(10));tx.executeWithoutResult(t->stays.record("C1","owner",false,now,150,15));assertEquals("AVAILABLE",jdbc.queryForObject("SELECT status FROM rooms",String.class));assertEquals(now.plusMonths(3),jdbc.queryForObject("SELECT end_date FROM contracts",java.sql.Date.class).toLocalDate());}
 @Test void expiryReleasesRoomButKeepsAnActiveLeaseOccupied(){LocalDate now=StayService.today();contract("C1","T1",now.minusMonths(2),now.minusDays(1));tx.executeWithoutResult(t->stays.refreshAll());assertEquals("AVAILABLE",jdbc.queryForObject("SELECT status FROM rooms",String.class));contract("C2","T2",now,now.plusMonths(2));tx.executeWithoutResult(t->stays.refreshAll());assertEquals("OCCUPIED",jdbc.queryForObject("SELECT status FROM rooms",String.class));}
 @Test void earlyCheckinAndWrongOwnerGuard(){LocalDate now=StayService.today();contract("C1","T1",now.plusDays(3),now.plusMonths(2));tx.executeWithoutResult(t->stays.record("C1","owner",true,now,100,10));assertEquals(now,StayService.date(stays.stay("C1").get("check_in")));doThrow(new ResponseStatusException(HttpStatus.FORBIDDEN)).when(landlords).requireOwner("other","R1");assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(t->stays.record("C1","other",false,now,110,11)));}
 @Test void noBackwardsOrFutureMetersDates(){LocalDate now=StayService.today();contract("C1","T1",now.minusDays(2),now.plusMonths(1));jdbc.update("INSERT INTO contract_stays VALUES('C1',?,null,100,10,null,null,3000000)",now.minusDays(2));assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(t->stays.record("C1","owner",false,now,99,11)));assertThrows(ResponseStatusException.class,()->tx.executeWithoutResult(t->stays.record("C1","owner",false,now.plusDays(1),110,11)));}
 @Test void lastDayBillingAndRestartCatchup(){assertEquals(YearMonth.of(2026,9),RentalJobs.dueMonth(LocalDateTime.of(2026,10,31,23,54)));assertEquals(YearMonth.of(2026,10),RentalJobs.dueMonth(LocalDateTime.of(2026,10,31,23,55)));assertEquals(YearMonth.of(2026,10),RentalJobs.dueMonth(LocalDateTime.of(2026,11,1,0,1)));}

 @Test void duplicateReadingsRequireReview(){janFixture();jdbc.update("INSERT INTO utility_readings VALUES('M2','R1',2026,1,300,400,10,20,3500,15000)");assertEquals("NEEDS_READING",bill("C1"));assertEquals(0,count("invoices"));}
 @Test void noConfirmedCheckinMeansNoAutomaticCharge(){janFixture();jdbc.update("UPDATE contract_stays SET check_in=null");assertEquals("NEEDS_READING",bill("C1"));assertEquals(0,count("invoices"));}
 @Test void existingRentIsPreservedWhenAddingUtilities(){janFixture();jdbc.update("INSERT INTO invoices VALUES('OLD','C1',2026,1,1500000,0,0,0,1500000)");assertEquals("CREATED",bill("C1"));assertEquals(1,count("invoices"));assertEquals(new BigDecimal("2000000.00"),jdbc.queryForObject("SELECT total_amount FROM invoices",BigDecimal.class));}
 @Test void paidReportRacingAutomaticBillKeepsAmount()throws Exception{janFixture();jdbc.update("INSERT INTO invoices VALUES('OLD','C1',2026,1,3100000,0,0,0,3100000)");CountDownLatch locked=new CountDownLatch(1),release=new CountDownLatch(1);var payer=CompletableFuture.runAsync(()->tx.executeWithoutResult(t->{jdbc.queryForList("SELECT invoice_id FROM invoices WHERE invoice_id='OLD' FOR UPDATE");locked.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new RuntimeException("timeout");}catch(InterruptedException e){throw new RuntimeException(e);}jdbc.update("INSERT INTO payment_reports VALUES(1,'OLD','PENDING')");}));assertTrue(locked.await(5,TimeUnit.SECONDS));var biller=CompletableFuture.supplyAsync(()->bill("C1"));release.countDown();payer.get(10,TimeUnit.SECONDS);assertEquals("MANUAL",biller.get(10,TimeUnit.SECONDS));assertEquals(new BigDecimal("3100000.00"),jdbc.queryForObject("SELECT total_amount FROM invoices",BigDecimal.class));}

 @Test void expiryHandlesVietnameseStatusAndKeepsMaintenance(){LocalDate now=StayService.today();contract("C1","T1",now.minusMonths(1),now.minusDays(1));jdbc.update("UPDATE rooms SET status='Đã thuê'");tx.executeWithoutResult(t->stays.refreshAll());assertEquals("AVAILABLE",jdbc.queryForObject("SELECT status FROM rooms",String.class));jdbc.update("UPDATE rooms SET status='MAINTENANCE'");tx.executeWithoutResult(t->stays.refreshAll());assertEquals("MAINTENANCE",jdbc.queryForObject("SELECT status FROM rooms",String.class));}
 @Test void missingEndDateDoesNotSilentlyVacateOccupiedRoom(){contract("C1","T1",StayService.today().minusDays(1),null);tx.executeWithoutResult(t->stays.refreshAll());assertEquals("OCCUPIED",jdbc.queryForObject("SELECT status FROM rooms",String.class));}
}
